  `updated_at` timestamp NULL DEFAULT NULL,
  `per` float GENERATED ALWAYS AS ((`points` + `rebounds` + `assists` + `steals` + `blocks` - (`field_goal_attempts` - `field_goals_made`) - `turnovers`) / nullif(`minutes`,0)) STORED,
