DROP TABLE IF EXISTS `mvp_leaders`;

DROP VIEW IF EXISTS `mvp_leaders`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `mvp_leaders`  AS SELECT `players`.`id` AS `player_id`, `players`.`name` AS `player_name`, `players`.`is_rookie` AS `is_rookie`, `players`.`draft_status` AS `draft_status`, `players`.`team_id` AS `team_id`, `teams`.`name` AS `team_name`, count(case when `player_game_stats`.`minutes` > 0 then `player_game_stats`.`game_id` end) AS `games_played`, round(sum(`player_game_stats`.`points`) / nullif(count(case when `player_game_stats`.`minutes` > 0 then 1 end),0),2) AS `points_per_game`, round(sum(`player_game_stats`.`rebounds`) / nullif(count(case when `player_game_stats`.`minutes` > 0 then 1 end),0),2) AS `rebounds_per_game`, round(sum(`player_game_stats`.`assists`) / nullif(count(case when `player_game_stats`.`minutes` > 0 then 1 end),0),2) AS `assists_per_game`, round(sum(`player_game_stats`.`steals`) / nullif(count(case when `player_game_stats`.`minutes` > 0 then 1 end),0),2) AS `steals_per_game`, round(sum(`player_game_stats`.`blocks`) / nullif(count(case when `player_game_stats`.`minutes` > 0 then 1 end),0),2) AS `blocks_per_game`, round(sum(`player_game_stats`.`turnovers`) / nullif(count(case when `player_game_stats`.`minutes` > 0 then 1 end),0),2) AS `turnovers_per_game`, round(sum(`player_game_stats`.`fouls`) / nullif(count(case when `player_game_stats`.`minutes` > 0 then 1 end),0),2) AS `fouls_per_game`, sum(`player_game_stats`.`points`) AS `total_points`, sum(`player_game_stats`.`rebounds`) AS `total_rebounds`, sum(`player_game_stats`.`assists`) AS `total_assists`, sum(`player_game_stats`.`steals`) AS `total_steals`, sum(`player_game_stats`.`blocks`) AS `total_blocks`, sum(`player_game_stats`.`turnovers`) AS `total_turnovers`, sum(`player_game_stats`.`fouls`) AS `total_fouls`, sum(`player_game_stats`.`points`) + sum(`player_game_stats`.`rebounds`) * 1.2 + sum(`player_game_stats`.`assists`) * 1.5 + sum(`player_game_stats`.`steals`) * 2 + sum(`player_game_stats`.`blocks`) * 2 - sum(`player_game_stats`.`turnovers`) * 1 - sum(`player_game_stats`.`fouls`) * 0.5 AS `performance_score` FROM (((`players` join `player_game_stats` on(`players`.`id` = `player_game_stats`.`player_id`)) join `teams` on(`players`.`team_id` = `teams`.`id`)) join `schedules` on(`player_game_stats`.`game_id` = `schedules`.`game_id`)) WHERE `player_game_stats`.`season_id` = (select max(`player_game_stats`.`season_id`) from `player_game_stats`) AND `schedules`.`round` not in ('play_ins_elims_round_1','play_ins_elims_round_2','play_ins_finals','quarter_finals','round_of_16','round_of_32','semi_finals','interconference_semi_finals','finals') GROUP BY `players`.`id`, `players`.`name`, `teams`.`name`, `players`.`is_rookie`, `players`.`draft_status`, `players`.`team_id` ORDER BY sum(`player_game_stats`.`points`) + sum(`player_game_stats`.`rebounds`) * 1.2 + sum(`player_game_stats`.`assists`) * 1.5 + sum(`player_game_stats`.`steals`) * 2 + sum(`player_game_stats`.`blocks`) * 2 - sum(`player_game_stats`.`turnovers`) * 1 - sum(`player_game_stats`.`fouls`) * 0.5 DESC LIMIT 0, 15 ;

