DROP TABLE IF EXISTS `player_playoff_status`;

DROP VIEW IF EXISTS `player_playoff_status`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `player_playoff_status`  AS SELECT `p`.`id` AS `player_id`, `p`.`name` AS `player_name`, count(case when `s`.`round` = 'round_of_16' then 1 end) AS `round_of_16_appearances`, count(case when `s`.`round` = 'quarter_finals' then 1 end) AS `quarter_finals_appearances`, count(case when `s`.`round` = 'semi_finals' then 1 end) AS `semi_finals_appearances`, count(case when `s`.`round` = 'interconference_semi_finals' then 1 end) AS `interconference_semi_finals_appearances`, count(case when `s`.`round` = 'finals' then 1 end) AS `finals_appearances`, count(distinct case when `se`.`finals_mvp_id` = `p`.`id` then `se`.`id` end) AS `finals_mvp_count`, group_concat(distinct `se`.`name` order by `se`.`name` ASC separator ', ') AS `seasons` FROM (((`players` `p` left join `player_game_stats` `pg` on(`p`.`id` = `pg`.`player_id`)) left join `schedules` `s` on(`pg`.`game_id` = `s`.`game_id`)) left join `seasons` `se` on(`s`.`season_id` = `se`.`id`)) GROUP BY `p`.`id`, `p`.`name` ;

